// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadMontserrat = makeLoadFont('Montserrat');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: montserratFamily } = loadMontserrat();



export type CacGraphProps = Record<string, any>;

const CacGraph: React.FC<CacGraphProps> = ({
  backgroundColor = "#030f35",
  transparentBackground = false,
  durationInSeconds = 6,
  title = "CAC",
  subtitle = "CUSTOMER ACQUISITION COST",
  titleColor = "#ffffff",
  subtitleColor = "#2dd4bf",
  barColors = ["#97cbf3", "#61b0ec", "#2d96eb", "#1773e3", "#2dd4bf"],
  arrowColor = "#ffffff",
  baselineColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout calculations
  const chartLeft = width * 0.12;
  const chartRight = width * 0.88;
  const chartWidth = chartRight - chartLeft;
  const baselineY = height * 0.82;
  const maxBarHeight = height * 0.35; 
  
  const numBars = Math.max(1, barColors.length);
  const barWidth = chartWidth / (numBars + (numBars - 1) * 0.25);
  const barGap = barWidth * 0.25;

  // Arrow drawing bounds
  const startFrame = 40;
  const endFrame = 100;
  const t = interpolate(frame, [startFrame, endFrame], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp"
  });

  // Bezier Control points dynamically adapting to array length
  const x0 = chartLeft + barWidth / 2 - 30 * s; 
  const y0 = baselineY - (maxBarHeight * 0.25) - 50 * s;
  
  const x3 = chartRight - barWidth / 2 + 10 * s;
  const y3 = baselineY - maxBarHeight - 200 * s;

  const x1 = x0 + (x3 - x0) * 0.5;
  const y1 = y0 - 10 * s;
  const x2 = x0 + (x3 - x0) * 0.7;
  const y2 = y3 + 50 * s;

  // De Casteljau (cubic) for path truncation and accurate tip tangent
  const L = (a: number, b: number, tVal: number) => a + (b - a) * tVal;
  const ax = L(x0, x1, t);
  const ay = L(y0, y1, t);
  const bx = L(x1, x2, t);
  const by = L(y1, y2, t);
  const cx = L(x2, x3, t);
  const cy = L(y2, y3, t);

  const dx = L(ax, bx, t);
  const dy = L(ay, by, t);
  const ex = L(bx, cx, t);
  const ey = L(by, cy, t);

  const tipX = L(dx, ex, t);
  const tipY = L(dy, ey, t);

  const angle = Math.atan2(ey - dy, ex - dx) * (180 / Math.PI);
  const partialD = `M ${x0} ${y0} C ${ax} ${ay}, ${dx} ${dy}, ${tipX} ${tipY}`;

  // Texts Entrance
  const textOpacity = interpolate(frame, [0, 20], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const textYOffset = interpolate(frame, [0, 20], [30 * s, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {/* TEXT LAYER */}
      <div
        style={{
          position: "absolute",
          top: height * 0.16,
          left: 0,
          width: "100%",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          opacity: textOpacity,
          transform: `translateY(${textYOffset}px)`,
          transition: "none",
        }}
      >
        <div style={{
          fontFamily: montserratFamily,
          fontWeight: 900,
          fontSize: 220 * s,
          lineHeight: 1,
          color: titleColor,
          letterSpacing: "-0.02em"
        }}>
          {title}
        </div>
        <div style={{
          fontFamily: interFamily,
          fontWeight: 700,
          fontSize: 38 * s,
          color: subtitleColor,
          marginTop: 15 * s,
          letterSpacing: "0.05em"
        }}>
          {subtitle}
        </div>
      </div>

      {/* CHART LAYER */}
      {barColors.map((color, i) => {
        const startOffset = 15 + i * 6;
        const progress = spring({
          frame: frame - startOffset,
          fps,
          config: { damping: 14, stiffness: 80 }
        });
        
        // Dynamically compute increasing height ratios along a gentle curve
        const normalizedI = numBars > 1 ? i / (numBars - 1) : 1;
        const ratio = 0.25 + 0.75 * Math.pow(normalizedI, 1.3);
        const finalH = maxBarHeight * ratio;
        const h = progress * finalH;
        
        const leftPos = chartLeft + i * (barWidth + barGap);

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              bottom: height - baselineY,
              left: leftPos,
              width: barWidth,
              height: h,
              backgroundColor: color,
              borderTopLeftRadius: 4 * s,
              borderTopRightRadius: 4 * s,
              opacity: frame >= startOffset ? 1 : 0,
              transition: "none",
            }}
          />
        );
      })}

      {/* BASELINE */}
      <div 
        style={{
          position: "absolute",
          left: chartLeft - 20 * s,
          top: baselineY,
          width: chartWidth + 40 * s,
          height: 6 * s,
          backgroundColor: baselineColor,
          borderRadius: 3 * s,
          opacity: interpolate(frame, [10, 25], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }),
          transform: `scaleX(${interpolate(frame, [10, 30], [0.8, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" })})`,
          transition: "none",
        }}
      />

      {/* ARROW LAYER */}
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          pointerEvents: "none",
          transition: "none",
        }}
      >
        {frame >= startFrame && t > 0.001 && (
          <path
            d={partialD}
            fill="none"
            stroke={arrowColor}
            strokeWidth={14 * s}
            strokeLinecap="round"
            style={{ transition: "none" }}
          />
        )}
        {frame >= startFrame && t > 0.001 && (
          <g transform={`translate(${tipX}, ${tipY}) rotate(${angle})`}>
            <polygon
              points={`0,0 -${45 * s},-${25 * s} -${35 * s},0 -${45 * s},${25 * s}`}
              fill={arrowColor}
              style={{ transition: "none" }}
            />
          </g>
        )}
      </svg>
    </AbsoluteFill>
  );
};

export default CacGraph;